package com.shopsphere.service; import com.shopsphere.dto.AuthDtos.*; import com.shopsphere.entity.*; import com.shopsphere.repository.AddressRepository; import com.shopsphere.security.CurrentUser; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import java.util.*; @Service public class AddressService {private final AddressRepository repo;private final CurrentUser current;public AddressService(AddressRepository r,CurrentUser c){repo=r;current=c;} public List<AddressResponse> all(Authentication a){return repo.findAllByUser(current.get(a)).stream().map(this::map).toList();} public AddressResponse create(Authentication a,AddressRequest r){Address x=new Address();x.setUser(current.get(a));x.setLine1(r.line1());x.setLine2(r.line2());x.setCity(r.city());x.setState(r.state());x.setPostalCode(r.postalCode());x.setCountry(r.country());repo.save(x);return map(x);} public Address get(UUID id,Authentication a){return repo.findByIdAndUser(id,current.get(a)).orElseThrow();} private AddressResponse map(Address x){return new AddressResponse(x.getId(),x.getLine1(),x.getLine2(),x.getCity(),x.getState(),x.getPostalCode(),x.getCountry());}}
